    // Sort the array to find quantiles
    a.sort_unstable();

    // To find the index corresponding to quantile q (percentage),
    // Use "nearest rank" method:
    //
    // index = ceil((q / 100) * n) - 1
    // where n = a.len()
    //
    // This means:
    // q=0    -> index = -1 (but handled above)
    // q=100  -> index = n-1 (handled above)
    //
